def analyze(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for row in g for x in row if x)
    lc=cnt.most_common(1)[0][0]
    # candidate line rows: only linecolor nonzeros
    rows=[r for r in range(H) if g[r] and all(x in (0,lc) for x in g[r]) and any(x==lc for x in g[r])]
    cols=[c for c in range(W) if all(g[r][c] in (0,lc) for r in range(H)) and any(g[r][c]==lc for r in range(H))]
    # strong: line rows must cross all line cols and vice versa
    rows=[r for r in rows if all(g[r][c]==lc for c in cols)]
    cols=[c for c in cols if all(g[r][c]==lc for r in rows)]
    return H,W,lc,rows,cols

