    rb=[-1]+rows; cb=[-1]+cols
    rranges=[(rb[i]+1,(rb[i+1] if i+1<len(rb) else H)-1) for i in range(len(rb))]
    cranges=[(cb[i]+1,(cb[i+1] if i+1<len(cb) else W)-1) for i in range(len(cb))]
    return rranges,cranges

